(() => {
  'use strict';
  const THEME_KEY = 'manglua-theme';
  const $ = (s, r = document) => r.querySelector(s);
  const $$ = (s, r = document) => [...r.querySelectorAll(s)];

  function systemDark() {
    return window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
  }

  function applyTheme(mode) {
    const dark = mode === 'dark' || (mode === 'auto' && systemDark());
    document.documentElement.classList.toggle('dark', dark);
    document.documentElement.style.colorScheme = dark ? 'dark' : 'light';
    $$('button.VPSwitchAppearance').forEach((button) => {
      button.setAttribute('aria-checked', String(dark));
    });
  }

  function toggleTheme() {
    const next = document.documentElement.classList.contains('dark') ? 'light' : 'dark';
    try { localStorage.setItem(THEME_KEY, next); } catch {}
    applyTheme(next);
  }

  function initTheme() {
    let mode = 'auto';
    try { mode = localStorage.getItem(THEME_KEY) || 'auto'; } catch {}
    applyTheme(mode);
    $$('button.VPSwitchAppearance').forEach((button) => {
      if (button.dataset.mangluaThemeBound) return;
      button.dataset.mangluaThemeBound = '1';
      button.addEventListener('click', (event) => {
        event.preventDefault();
        event.stopImmediatePropagation();
        toggleTheme();
      }, true);
    });
    if (window.matchMedia) {
      const media = window.matchMedia('(prefers-color-scheme: dark)');
      media.addEventListener?.('change', () => {
        try { if ((localStorage.getItem(THEME_KEY) || 'auto') === 'auto') applyTheme('auto'); } catch { applyTheme('auto'); }
      });
    }
  }

  const INDEX = [{"url":"404.html","title":"404 | MLua","text":"404 | MLua"},{"url":"index.html","title":"MLua","text":"MLua Skip to content MLua Search K Main Navigation MLua English Русский English Русский Appearance MLua Modding for Unity games Language Prelude MLua language reference"},{"url":"mlua/classes.html","title":"Classes and Interfaces | MLua","text":"Classes and Interfaces ​ Classes let you bundle fields and methods into clean, reusable types. Interfaces let you define contracts that those classes must follow. Together, they give MLua a full-featured object-oriented programming system - compiled down to fast tables and userdata at runtime, with static type checking before your code ever runs. If you&#39;ve used C#, Java, or TypeScript, you&#39;ll feel right at home. The main differences in MLua are that self is written explicitly in methods, and super calls use a simple helper function. Declaring a Class ​ Here is a straightforward counter class: lua class Counter public value : number = 0 public function Increment (): number self . value = self . value + 1 return self . value end end Declaring a class creates a new named type. You can define it globally or inside a namespace . Close the class body with end . Inside any method, self refers to the current instance. Members ​ You can define fields, methods, constructors, and static members in whatever combination you need: Member Kind Example Syntax What it does Field public value: number = 0 Instance variable initialized when an object is created Method public function Name(args): ReturnType ... end Function callable on instances with obj:Name() Constructor public function init(args) ... end Initializes a new instance when created Static field public static count: number = 0 Belongs to the class itself, accessed via Counter.count Static method public static function Create(): Counter ... end Called directly on the class: Counter.Create() Access Modifiers ​ Every member has a visibility level to help you keep your code clean and prevent bugs: Modifier Who can see it public Anyone, from anywhere. This is the default if omitted. protected Only the class that declared it and its subclasses. private Only the specific class that declared it. Inheritance ​ A class inherits from a parent class using : BaseName : lua class Base public virtual function Value (): number return 1 end end class Child : Base public override function Value (): number return super ( self , Child, &quot;Value&quot; ) + 1 end end Inheritance keywords: Keyword What it does override Required whenever you replace an inherited method from a base class. final Prevents child classes from overriding this method further down. abstract Declares a method signature without a body - must be implemented by subclasses. abstract class Marks a class that cannot be directly instantiated with new . To call the parent class&#39;s version of a method, use super(self, CurrentClass, &quot;MethodName&quot;, args...) . Abstract Classes ​ Abstract classes let you define a template for other classes to build upon: lua abstract class Shape public abstract function Area (): number end class Circle : Shape public radius : number = 1 public override function Area (): number return 3.14159 * self . radius * self . radius end end Creating Instances ​ MLua gives you three interchangeable ways to create an instance and call its constructor init : lua local a = Counter. new () -- lowercase .new() local b = Counter. New () -- uppercase .New() local c = new Counter () -- new keyword, just like in C# or Java All arguments are automatically forwarded to your init method: lua class Person private name : string = &quot;&quot; public function init (name: string ) self . name = name end public function GetName (): string return self . name end end local person = new Person ( &quot;PlayerOne&quot; ) print ( person : GetName ()) -- &quot;PlayerOne&quot; If a class doesn&#39;t declare an init method, instances are created with all fields set to their declared defaults. Interfaces ​ Interfaces declare a contract of methods that implementing classes promise to provide. Interfaces hold no state - they contain no fields and no implementation code. Short form - great when you just need to list member names: lua interface IValue (Value) interface IDrink (MakeDrink, Refill) Block form - when you want to specify full parameter and return types: lua interface IShape public function Area (): number public function Scale (factor: number ) end Implementing an interface uses the implements keyword: lua class CoffeeCup : Person implements IDrink public function MakeDrink (): string return &quot;espresso&quot; end public function Refill () print ( &quot;Refilled!&quot; ) end end A class can implement as many interfaces as you want: implements IDrink, IValue, IShape . If you forget to implement any declared method, the compiler will tell you immediately. Complete Example ​ Here is how abstract base classes and interfaces fit together in practice: lua abstract class Entity implements IShape public abstract function Area (): number public name : string = &quot;entity&quot; end class Box : Entity public width : number = 1 public height : number = 1 public override function Area (): number return self . width * self . height end end local box = new Box () box. width = 4 box. height = 3 print ( &quot;Area:&quot; , box : Area ()) -- 12 Next Steps ​ Topic What you&#39;ll learn Types and Annotations Adding static type annotations to variables and methods Enums and Generics Declaring enums and generic container classes Namespaces and Modules Organizing classes into namespaces and importing modules Prelude Library Built-in helper functions for tables, strings, and OOP"},{"url":"mlua/definitions.html","title":"Definitions and Conditional Compilation | MLua","text":"Definitions and Conditional Compilation ​ Definitions are compile-time flags evaluated by MLua before your chunk is compiled. They let you easily turn features on or off, support different game versions, or separate debug code from release builds. Declaring Values ​ You can define flags right at the top of your Lua files using #define : lua # define SHOW_COUNTER true # define LIMIT 10 # define MOD_NAME &quot;ExampleMod&quot; # ifdef SHOW_COUNTER print ( &quot;Counter feature is enabled!&quot; ) # endif Writing #define NAME by itself defines NAME as true . You can also assign booleans, numbers, or double-quoted strings. Note that directive names are case-sensitive. Available Directives ​ Directive What it does #define NAME value Defines a flag or value in the active branch #undef NAME Removes a previously defined flag #ifdef NAME Checks if a flag has been defined #ifndef NAME Checks if a flag has not been defined #if NAME Checks if a definition evaluates to true #ifnot NAME Checks if a definition evaluates to false #elif NAME , #elseif NAME Alternative conditional branch #else Fallback branch if previous conditions were false #endif , #end Closes the conditional block Conditions take a flag name, optionally prefixed by ! or not . This is a clean conditional compilation tool - arithmetic expressions like #if VERSION &gt;= 2 are not supported. lua # define FEATURE false # ifdef FEATURE print ( &quot;FEATURE is defined&quot; ) # endif #if FEATURE print ( &quot;This line will not be compiled&quot; ) #else print ( &quot;FEATURE is disabled&quot; ) # endif # undef FEATURE Lines inside inactive branches are simply skipped, preserving line numbering for accurate error messages. Flags Provided by the Game ​ Games can also inject global runtime flags into your environment through the DEFINE table. You can check for them using defined(name) : lua if defined ( &quot;GAME_VERSION&quot; ) then print ( &quot;Running under game version:&quot; , DEFINE[ &quot;GAME_VERSION&quot; ]) end"},{"url":"mlua/diagnostics.html","title":"Diagnostics | MLua","text":"Diagnostics ​ Every diagnostic carries a code, a source location, and a message. Codes are grouped by the compiler stage that produced them, so the prefix alone tells you roughly where in the pipeline the problem was caught. Code Ranges ​ Range Stage Meaning MLUA1xxx Lexer Malformed tokens: unterminated strings, bad numbers, invalid escapes MLUA3xxx Parser Grammar errors: missing end , unexpected token, malformed declaration MLUA42xx Access Visibility violations on private and protected members MLUA43xx Declarations Bad override , final , abstract , or interface implementation MLUA44xx Types Unknown members, wrong argument types, invalid assignments and operators Errors are always reported using the code from the earliest stage that fails. A chunk with a lexer error, for example, is never parsed or type-checked, since later stages depend on earlier ones succeeding. Frequently Seen Codes ​ Code Message Typical cause MLUA3001 unexpected token after chunk body An extra end , or a block closed twice MLUA3013 unexpected token in type body A plain statement placed inside a class or interface body MLUA3017 expected an expression A declaration keyword used where a value was expected MLUA4206 member is private to a class A private member read from outside its declaring class MLUA4207 member is protected in a class A protected member read from outside the class hierarchy MLUA4403 operator applied to the wrong type For example, # used on a value that has no length MLUA4404 cannot assign one type to another The annotation and the assigned value&#39;s type don&#39;t match MLUA4410 type has no member named ... A typo, the wrong type, or a member that was never declared MLUA4411 argument expects one type but received another A call argument doesn&#39;t satisfy the parameter&#39;s declared type MLUA4412 enum member is read only An assignment targets an enum member instead of a variable Reading a Diagnostic ​ Diagnostics follow a fixed format: =test:24:52 MLUA4206: secret is private to Base Part Meaning =test The chunk name - typically the file being compiled 24:52 Line and column where the offending token starts MLUA4206 The diagnostic code (remainder) A human-readable explanation of what was rejected and why This format is stable and safe to parse with tooling - editors and build scripts can extract the chunk, position, and code with a simple pattern match. Severity ​ There is only one severity level: error . A chunk with at least one diagnostic does not run - a mistyped member name, an illegal override, or a type mismatch is caught before the game ever executes that code, rather than surfacing as a runtime crash mid-session. There are no warnings and no suppression directives (no // eslint-disable -style escape hatch). If you deliberately want a check relaxed for a specific value, annotate it as any or object instead - this makes the relaxation visible in the source rather than hidden in a comment. Strict analysis versus runtime-checked execution ​ The strict mode used by AnalyzeSource reports all type and access errors. The runtime-checked mode used during execution keeps syntax and type-mismatch errors but allows dynamic fields."},{"url":"mlua/environment.html","title":"MLua and the game | MLua","text":"MLua and the game ​ Who runs the script? ​ A game developer embeds MangLua into their game and decides which scripts and APIs are available. As a mod author, you write MLua against that exposed API. The running game is sometimes called the host application . Three different kinds of capability ​ Layer Provides Does not provide Lua VM Values, functions, tables, coroutines and selected standard libraries Access to every game type MLua language and prelude Classes, access rules, enums, generic specializations and helper functions Automatic permission to patch methods or create components Game integration Registered managed types, API modules, component binding and configured patch backend A guarantee that every C# feature or every native calling convention works A script can use a capability only if the required layers are present. A complete example with no implicit object ​ This example requires the game to expose Unity&#39;s GameObject and PrimitiveType . lua give UnityEngine local cube = GameObject. CreatePrimitive (PrimitiveType. Cube ) cube. name = &quot;MLua cube&quot; print (cube. name ) Here cube is a local variable containing the object returned by CreatePrimitive . Nothing called host is assumed to exist. Feature availability ​ Before writing a mod, check what capabilities and types the game provides. See Working with Unity , Class injection , Patching and Definitions ."},{"url":"mlua/generics.html","title":"Enums and generics | MLua","text":"Enums and generics ​ Enums are immutable named collections of values ​ lua enum Element { Fire, Water = 5 , Air } assert (Element. Fire == 0 ) assert (Element. Water == 5 ) assert (Element. Air == 6 ) assert (Element. name ( 5 ) == &quot;Water&quot; ) assert ( # Element == 3 ) Members are ordinary underlying values, not objects carrying .name . Use Element.name(value) for reverse lookup. typeof(Element.Fire) therefore does not promise the enum type name. Element.Fire is a number. Expression Result Element.name(value) First registered member name for the value, or nil Element.value(name) Value for a name, or nil Element.has(name) Whether the name exists Element.names() Ordered list of names Element.values() Ordered list of values #Element Number of entries kindof(Element) &quot;enum&quot; isenum(Element) true Unknown direct member reads and assignments raise at runtime. The strict analyzer also reports unknown members and immutable-member writes. In runtime-checked execution those operations remain catchable: lua assert ( not pcall ( function () return Element. Missing end )) assert ( not pcall ( function () Element. Fire = 1 end )) Generic classes ​ lua class Box &lt;T&gt; private item = nil public function init (value) self . item = value end public function Get () return self . item end public function Argument () return typeargs ( self ). T end end local box = new Box &lt;Element&gt; (Element. Water ) assert ( box : Get () == 5 ) assert ( box : Argument () == Element) assert ( typeof (box) == &quot;Box&lt;Element&gt;&quot; ) assert ( instanceof (box, Box)) Specialization is performed by the MLua runtime. Repeated specialization with the same type arguments is cached. Generic functions and component calls ​ lua local function AddComponent &lt; T : Component &gt;(target: object ): object return target : AddComponent &lt;T&gt; () end This function requires the game to expose Component and the component API used by its caller. The type argument is forwarded to the managed operation. A generic parameter used as a managed type must resolve to an exposed type or class. The runtime handles constrained forwarding and AddComponent type inference directly."},{"url":"mlua/injection.html","title":"Class Injection | MLua","text":"Class Injection ​ Want your MLua script to behave just like a native Unity MonoBehaviour ? That is exactly what class injection does. While an ordinary class is just a script object, an injected component is an actual Unity component attached to a GameObject that receives standard Unity lifecycle events like Update , Start , and Awake . Complete Example ​ Here is how you create a component that rotates a cube every frame: lua give UnityEngine @[ Component ( &quot;Spinner&quot; )] class Spinner : MonoBehaviour public speed = 90 public function Update () self . transform . Rotate ( 0 , self . speed * Time. deltaTime , 0 ) end end -- Create a cube and attach our custom MLua component to it local cube = GameObject. CreatePrimitive (PrimitiveType. Cube ) local spinner : Spinner = cube : AddComponent &lt;Spinner&gt; () -- Access its properties spinner. speed = 45 -- Verify it is on the GameObject assert ( cube : GetComponent &lt;Spinner&gt; () == spinner) In this example: cube is the Unity GameObject . spinner is your custom MLua component instance. Inside any method, self refers to your component instance. self.gameObject gives you the attached GameObject . self.transform gives you its Transform . The @[Component] Attribute ​ The @[Component(&quot;Spinner&quot;)] attribute gives your class a component alias. This registers your script class with the engine&#39;s component system so Unity knows how to instantiate and route messages to it. Adding and Finding Components ​ You can attach components using generic syntax or by inferring the type from an annotated local variable: lua -- Explicit generic syntax local spinner : Spinner = cube : AddComponent &lt;Spinner&gt; () -- Or automatic inference from local variable type local spinner : Spinner = cube : AddComponent () -- Fetch an existing component from the object local found : Spinner = cube : GetComponent &lt;Spinner&gt; () assert (found == spinner) GetComponent looks for an existing component on that GameObject - it will return nil if one hasn&#39;t been added yet. Inheritance and Base Components ​ You can build hierarchies of components using inheritance and abstract classes: lua @[ Component ( &quot;BaseMotor&quot; )] abstract class BaseMotor : MonoBehaviour public ticks = 0 public function Update () self . ticks = self . ticks + 1 end end @[ Component ( &quot;FastMotor&quot; )] class FastMotor : BaseMotor public function Start () print ( &quot;FastMotor started!&quot; ) end end -- Attach the concrete derived component local motor : FastMotor = cube : AddComponent &lt;FastMotor&gt; () -- Fetch it by its base type local base : BaseMotor = cube : GetComponent &lt;BaseMotor&gt; () assert (base == motor) Note that abstract classes cannot be added directly to a GameObject . Unity Lifecycle Events ​ MLua components receive standard Unity lifecycle callbacks. While init is the constructor for the script instance, you should use Awake or Start for anything that needs the bound GameObject or Transform : Method When Unity calls it Awake() Called immediately when the component is created and attached to the GameObject OnEnable() Called whenever the GameObject or component becomes active/enabled Start() Called once before the very first frame update Update() Called every single frame - perfect for movement, input, and timers FixedUpdate() Called on a fixed physics timestep - ideal for Rigidbody physics calculations LateUpdate() Called every frame after all Update calls have finished - great for camera tracking OnDisable() Called whenever the GameObject or component is deactivated OnDestroy() Called right before the component or GameObject is destroyed Troubleshooting ​ Problem Solution MonoBehaviour not found Make sure you included give UnityEngine at the top of your script Method doesn&#39;t run every frame Double check the spelling of Update() , FixedUpdate() , or Start() Cannot add abstract class You cannot attach an abstract class directly - create and attach a concrete subclass instead Component returns nil on GetComponent Ensure you called AddComponent on the object first, or check that you are querying the right GameObject"},{"url":"mlua/language.html","title":"MLua Language Reference | MLua","text":"MLua Language Reference ​ MLua is a strict superset of Lua 5.4, so every valid Lua 5.4 chunk is valid MLua without modification. All standard Lua behaviour is preserved exactly: comments, strings, numbers, operators, control flow, closures, varargs, multiple returns, metatables, coroutines, and goto . Everything described on this page is either inherited directly from Lua or is a purely additive MLua extension. This reference assumes familiarity with at least one statically typed language such as C#, TypeScript, or Java. Lua-specific concepts such as metatables and coroutines are not explained here - see the Lua Reference Manual for those. Chunks ​ A chunk is a sequence of statements. Semicolons between statements are never required - a bare ; is accepted as an empty statement. lua local message = &quot;hello&quot; print (message) Comments ​ Line and block comments follow standard Lua syntax: lua -- Line comment --[[ Block comment spanning multiple lines ]] Values ​ MLua shares Lua&#39;s eight value types: Type Description nil The absence of a value boolean true or false number Integer or float subtype string Immutable byte sequence table Associative array and the basis for all objects function First-class callable value userdata Host-managed object (e.g. a Unity component) thread Coroutine MLua introduces no new runtime value kinds. Classes, interfaces, and enums are a compile-time layer built on top of tables and userdata. Variables ​ Local, global, constant, and to-be-closed variables all follow Lua 5.4 syntax: lua local count = 0 local a, b, c = 1 , 2 -- c is nil local frozen &lt;const&gt; = 10 -- compile-time constant local handle &lt;close&gt; = open () -- closed automatically when the scope exits globalValue = 1 -- global assignment (no &#39;local&#39; keyword) Any local variable may carry an optional type annotation. The compiler verifies it before the chunk runs: lua local speed : number = 90 local owner : Player = FindPlayer () → See Types and Annotations for the full type system, inference rules, and assignability. Operators ​ MLua keeps all Lua 5.4 operators and adds type queries and safe member access: Group Operators Arithmetic + - * / // % ^ unary - Bitwise &amp; | ~ &lt;&lt; &gt;&gt; unary ~ Comparison == ~= &lt; &lt;= &gt; &gt;= Logical and or not String / size .. # Type helper calls instanceof(v, C) implements(v, I) typeof(v) kindof(v) classof(v) Safe access ?. ?? Precedence follows Lua 5.4. Type queries use ordinary function calls, not infix operators. Compound assignments ( += , -= , *= , …) are also supported. lua local label = enemy?. name ?? &quot;unknown&quot; -- nil-safe access with fallback local isEnemy = instanceof (value, Enemy) -- runtime type check local typeName = typeof (value) -- returns the type name as a string Control Flow ​ All Lua 5.4 control structures are available. MLua adds continue for skipping to the next loop iteration: lua -- Conditional if value &gt; 10 then print ( &quot;high&quot; ) elseif value &gt; 0 then print ( &quot;low&quot; ) else print ( &quot;zero&quot; ) end -- While loop while active do step () end -- Repeat-until repeat step () until done -- Numeric for with continue for index = 1 , 10 , 2 do if index == 5 then continue end print (index) end -- Generic for for key, value in pairs (source) do print (key, value) end -- Explicit scope block do local scoped = 1 end Loop controls: Statement Behaviour break Exits the innermost loop continue Skips to the next iteration (MLua only) goto label / ::label:: Unconditional jump, as in Lua 5.4 Functions ​ Functions are first-class values and support all Lua 5.4 declaration forms: lua -- Local named function local function add (a, b) return a + b end -- Global function with varargs function Global (a, ...) return a, select ( &quot;#&quot; , ... ) end -- Function expression local handler = function (event) end -- Method with implicit self local target = {} function target : Method (value) return self , value end Parameters and return types accept optional annotations, checked by the compiler before the chunk runs: lua local function Distance (from: Vector3 , to: Vector3 ): number return (to - from). magnitude end → See Types and Annotations for annotating functions, overloads, and generics. Statement Summary ​ Statement Form Local declaration local a, b = 1, 2 Local with type local a: number = 1 Assignment a.b, c = 1, 2 Compound assignment a += 1 a -= 1 … Function call f() obj:m() Scope block do ... end Conditional if ... then ... elseif ... else ... end While loop while ... do ... end Repeat loop repeat ... until ... Numeric for for i = start, stop, step do ... end Generic for for k, v in iter do ... end Jump break continue goto return Function function f() end local function f() end Type declaration class interface enum Namespace namespace Name ... end API import give Name import Name Attribute @[Name(args)] before a declaration Where to Go Next ​ Topic Description Types and Annotations Built-in types, inference, assignability, and type queries Classes and Interfaces Inheritance, constructors, access modifiers, and static members Prelude Standard library and game-provided modules Modules give , import , and how game APIs are registered"},{"url":"mlua/managed-api.html","title":"Working with Unity and Game APIs | MLua","text":"Working with Unity and Game APIs ​ When writing mods in MLua, you aren&#39;t just writing isolated scripts - you have full access to Unity&#39;s engine and the game&#39;s own systems. You can spawn objects, move them around, hook into physics, manipulate cameras, and call game functions directly from Lua. Importing Unity ​ To start using Unity types in your script, simply request the namespace using give : lua give UnityEngine local player = GameObject. Find ( &quot;Player&quot; ) if player ~= nil then print ( &quot;Found player at: &quot; .. tostring (player. transform . position )) end Once loaded, standard Unity types like GameObject , Transform , Vector3 , Time , and Mathf are ready to use. Working with GameObjects ​ Finding, creating, and modifying game objects is straightforward: lua give UnityEngine -- Find an existing object in the scene local boss = GameObject. Find ( &quot;BossEnemy&quot; ) -- Find an object by tag local spawnPoint = GameObject. FindWithTag ( &quot;Respawn&quot; ) -- Create a brand new primitive object local cube = GameObject. CreatePrimitive (PrimitiveType. Cube ) cube. name = &quot;MyModCube&quot; -- Move it somewhere in the world cube. transform . position = Vector3 ( 0 , 10 , 0 ) Getting and Adding Components ​ GameObjects in Unity are containers for components. You can fetch existing components from an object or attach new ones: lua give UnityEngine local light = cube : GetComponent &lt;Light&gt; () if light == nil then -- Add a component if it doesn&#39;t have one light = cube : AddComponent &lt;Light&gt; () end -- Configure component properties light. color = Color. red light. intensity = 5.0 You can also attach custom MLua classes that you defined with @[Component] - see Class injection for details. Properties and Fields ​ You can read and write object properties just like normal Lua table fields: lua give UnityEngine local player = GameObject. Find ( &quot;Player&quot; ) local transform = player. transform -- Read current position local currentPos = transform. position print ( &quot;X:&quot; , currentPos. x , &quot;Y:&quot; , currentPos. y , &quot;Z:&quot; , currentPos. z ) -- Move the player forward transform. position = currentPos + Vector3 ( 0 , 0 , 5 ) -- Inspect frame timing local delta = Time. deltaTime Calling Methods ​ Calling methods on Unity objects uses the standard Lua colon syntax :Method() : lua give UnityEngine local rb = player : GetComponent &lt;Rigidbody&gt; () if rb ~= nil then -- Call instance method rb : AddForce (Vector3. up * 10 , ForceMode. Impulse ) end -- Call static method local dist = Vector3. Distance (player. transform . position , cube. transform . position ) print ( &quot;Distance to cube:&quot; , dist) Vectors and Math ​ Standard Unity math and vector helpers work seamlessly in your scripts: lua give UnityEngine -- Construct vectors local spawn = Vector3 ( 10 , 0 , 10 ) local offset = Vector3 ( 0 , 2 , 0 ) local target = spawn + offset -- Vector operations local direction = (target - spawn). normalized local distance = Vector3. Distance (spawn, target) -- Color helpers local highlight = Color ( 1.0 , 0.5 , 0.0 , 1.0 ) Working with C# Collections ​ When the game returns a C# List or array, you can inspect and iterate over its items using the collection methods: lua local inventory = player : GetComponent &lt;Inventory&gt; () local items = inventory. Items -- Check item count print ( &quot;Inventory count:&quot; , items. Count ) -- Retrieve items by 0-based or 1-based index for i = 0 , items. Count - 1 do local item = items : Get (i) print ( &quot;Item:&quot; , item. name ) end Game-Specific Namespaces ​ Besides Unity&#39;s own namespaces, games often make their own gameplay namespaces available. You load them the exact same way: lua give Game. Combat give Game. Inventory local weapon = WeaponDatabase. GetWeapon ( &quot;Excalibur&quot; ) print ( &quot;Damage:&quot; , weapon. BaseDamage ) If a namespace or type isn&#39;t provided by the game, MLua will report a clean error when compiling your script, telling you exactly what type could not be resolved."},{"url":"mlua/modules.html","title":"Modules and attributes | MLua","text":"Modules and attributes ​ Loading a registered module ​ lua give UnityEngine give Mang. Reflection give requests a module registered in your script environment. The module controls what it exposes. A source module is executed and cached after successful loading. Cyclic imports and missing modules will report an error. Registering a replacement source invalidates its cache entry. give UnityEngine makes Unity types like GameObject , Transform , and Vector3 available to your script. For details on working with Unity objects, see Working with Unity . For modules written as ordinary Lua files, you can also use a restricted require backed by registered sources. To alias a type locally, load its module and assign it to a local variable: lua give UnityEngine local Vec = UnityEngine. Vector3 local position = Vec ( 0 , 1 , 0 ) Namespaces ​ lua namespace Game. Combat class Weapon public damage = 10 end end local weapon = new Game. Combat . Weapon () A namespace groups declarations under a path. Chunk globals and imported values are still shared within the same script environment. Attributes ​ An attribute attaches metadata to the declaration that follows it: lua @[ Component ( &quot;Spinner&quot; )] class Spinner : MonoBehaviour public speed = 90 end Form: @[Name] or @[Name(arguments)] Multiple attributes may precede a single declaration Patch attributes accept a target plus options such as owner = &quot;example&quot; Built-in handlers such as Component , Prefix , Postfix , and Replace configure runtime behaviors like Unity component binding or method detours The managed API provides typed attribute readers and allows registering custom handlers. Multiple files ​ Files are compiled as chunks. To use declarations from another file, ensure that file has been loaded or registered as a module before referencing its global classes. Keep mod names, chunk names, and component scopes stable across reloads to avoid conflicts with other mods."},{"url":"mlua/patching.html","title":"Patching | MLua","text":"Patching ​ Class injection lets you add brand new behavior to a Unity game. But what if you want to change code that&#39;s already compiled into the game? That&#39;s where patching comes in. MLua lets you hook and detour managed methods right at runtime - similar in spirit to Harmony, but built directly into the language with clean attributes on ordinary Lua functions. Every patch function receives exactly one argument: frame . Think of frame as the function call&#39;s execution context ( context ). It gives you live, direct access to the call: the incoming arguments, the return slot, the current stage of execution, and a scratch slot ( frame.State ) to pass your own data between before and after stages of the same hook. Declaring a Patch ​ Loading give Mang.Patches gives you access to patch management functions. To patch a method, attach a patch attribute directly above a local function . The attribute specifies the target method, the argument count (to pick the right overload), and optional settings: lua give Mang. Patches @[ Prefix ( &quot;Assembly-CSharp::PatchExample.TakeDamage&quot; , 1 , owner = &quot;my-mod&quot; )] local function BlockBigHits (frame) if frame. Integer0 &gt; 100 then frame. Integer0 = 0 end end Here is how that breaks down: The attribute name ( Prefix , Postfix , Replace , Around , …) is the patch kind - it determines when your hook runs relative to the original game method. The target string is the fully qualified method name: Assembly::Namespace.Type.Method . The number right after the target is the argument count, which disambiguates overloads. Any following arguments are name = value options, like owner = &quot;my-mod&quot; . You can also write the owner positionally, or drop the argument count if the method name is unique: lua @[ Prefix ( &quot;Assembly-CSharp::PatchExample.TakeDamage&quot; , 1 , CoolMod)] @[ Prefix ( &quot;Assembly-CSharp::PatchExample.Reload&quot; , CoolMod)] @[ Prefix (PatchExample. Reload , CoolMod)] Any positional argument that isn&#39;t a number or key-value option is treated as the owner name. So CoolMod and owner = &quot;CoolMod&quot; do the exact same thing. Quotes are only needed if your owner name has spaces or commas. You can leave out the argument count if there&#39;s only one method with that name. You can even write the target unquoted as a dotted path (like PatchExample.Reload ) when it resolves unambiguously across loaded assemblies. Always put the hook function right beneath its attribute as a local function . Patch Kinds ​ Attribute When it runs @[Prefix] Runs before the original method. Great for reading or modifying incoming arguments. @[Postfix] Runs after the original method finishes successfully. Perfect for checking or rewriting the return value. @[Replace] Runs instead of the original method - skips the original game code entirely. @[Around] Wraps the original method - runs once before it and once after it. @[Finalizer] Runs on the exit path of the call, even if errors happen. @[Patch] An alias for @[Prefix] (pass kind = &quot;Postfix&quot; or similar to change it). If multiple mods patch the same method, they compose cleanly into a chain instead of clobbering each other: all prefixes run first, then the original method (unless skipped or replaced), then all postfixes, and finally any finalizers. The Frame (Function Context) ​ The frame argument represents the live call context ( context ) of the target method. When you read or write a slot on frame , you are directly reading or modifying the actual CPU registers and stack slots that the managed method uses: Slot What it represents in the context frame.Integer0 , frame.Integer1 , … Incoming integer and pointer arguments (registers RDX, R8, R9, etc.) frame.Float0 , frame.Float1 , … Incoming floating-point arguments (XMM / floating registers) frame.ReturnInteger Primary return value for integers, booleans, enums, or object references frame.ReturnInteger1 Secondary integer return register for composite structures or 128-bit values frame.ReturnFloat , frame.ReturnFloat1..3 Return values for floats, doubles, or homogeneous vector structs (Vector2, Vector3, Vector4, Quaternion) frame.ReturnVector , frame.ReturnVector1..3 SIMD / vector return slots frame.IndirectResult Pointer to caller-allocated memory for large struct returns frame.Stage 0 when entering before the original runs, 1 when leaving after it frame.State A scratchpad value you can use to pass info from stage 0 to stage 1 Here is how common C# types map onto the frame slots: Parameter or Return Type Mapped Frame Slot int , uint , long , ulong , byte , bool , char , enums frame.IntegerN / frame.ReturnInteger float , double frame.FloatN / frame.ReturnFloat Structs / vectors ( Vector2 , Vector3 , Vector4 , Quaternion ) frame.ReturnFloat , frame.ReturnFloat1..3 or frame.IndirectResult Reference types: string , object , arrays, classes Passed as a native pointer in frame.IntegerN Instance methods ( this ) Allowed - this occupies frame.Integer0 , and first arg becomes Integer1 frame.State always starts at 0 for a fresh call. It is dedicated to letting a single @[Around] handler pass custom state from its pre-call phase to its post-call phase. Prefix ​ Prefix runs before the original game method. If you change an argument slot on frame , the game code actually sees your new value: lua @[ Prefix ( &quot;Assembly-CSharp::PatchExample.Heal&quot; , 1 , owner = &quot;my-mod&quot; )] local function DoubleHealing (frame) frame. Integer0 = frame. Integer0 * 2 end Postfix ​ Postfix runs right after the original game method finishes. You can inspect what the game computed and alter the final return value: lua @[ Postfix ( &quot;Assembly-CSharp::PatchExample.GetScore&quot; , 0 , owner = &quot;my-mod&quot; )] local function AddBonus (frame) frame. ReturnInteger = frame. ReturnInteger + 10 end Replace ​ Replace runs instead of the original method. The original game code never runs at all, and your Lua function is entirely responsible for setting the return value: lua @[ Replace ( &quot;Assembly-CSharp::PatchExample.GetPrice&quot; , 0 , owner = &quot;my-mod&quot; )] local function AlwaysFree (frame) frame. ReturnInteger = 0 end Around and Skipping ​ An @[Around] hook is invoked twice during a single call: first at frame.Stage == 0 (before original), and then at frame.Stage == 1 (after original). You can use frame.State to remember values across the two calls: lua @[ Around ( &quot;Assembly-CSharp::PatchExample.TakeDamage&quot; , 1 , owner = &quot;my-mod&quot; )] local function ClampDamage (frame) if frame. Stage == 0 then frame. State = frame. Integer0 if frame. Integer0 &gt; 50 then frame. Integer0 = 50 end else print ( &quot;damage was&quot; , frame. State , &quot;now&quot; , frame. ReturnInteger ) end end If you return 1 from the enter stage ( frame.Stage == 0 ), MLua skips the original method completely: lua @[ Around ( &quot;Assembly-CSharp::PatchExample.Buy&quot; , 1 , owner = &quot;my-mod&quot; )] local function FreePurchases (frame) if frame. Stage == 0 then frame. ReturnInteger = 1 return 1 end end When multiple @[Around] hooks exist on one method, they nest cleanly like layers of an onion: entering in order, and exiting in reverse order. Finalizer ​ Finalizers execute on the leave path of the call, ensuring clean cleanup: lua @[ Finalizer ( &quot;Assembly-CSharp::PatchExample.AddXp&quot; , 1 , owner = &quot;my-mod&quot; )] local function ObserveCompletion (frame) assert (frame. Stage == 1 ) print ( &quot;result&quot; , frame. ReturnInteger ) end Overloads and Typed Targets ​ When a method has several overloads, disambiguate them by writing parameter types in parentheses right in the target string. Common C# aliases ( int , float , string , etc.) are recognized automatically: lua @[ Prefix ( &quot;Assembly-CSharp::PatchExample.Select(System.Int32)&quot; , owner = &quot;my-mod&quot; )] local function SelectInt (frame) frame. Integer0 = frame. Integer0 * 2 end If the parameter count alone is unique, you can just pass the integer arity. Options ​ Option What it does owner = &quot;...&quot; Identifier for your mod - essential if you want to cleanly remove your patches later priority = n Controls execution order among multiple hooks on the same target args = n , arity = n Alternative way to specify parameter count before = &quot;a, b&quot; Ensures your hook runs before the specified owners after = &quot;a, b&quot; Ensures your hook runs after the specified owners kind = &quot;Postfix&quot; Changes the hook type when using generic @[Patch] Always set owner explicitly so you can cleanly uninstall your hooks on mod reload. Removing Patches ​ The Mang.Patches module lets you remove hooks cleanly at runtime: Function Description Mang.Patches.installed() Returns the number of currently active patches Mang.Patches.unpatchOwner(owner) Removes every patch belonging to a specific mod owner Mang.Patches.unpatchTarget(target) Removes all patches attached to a specific method Mang.Patches.unpatchAll() Removes all active patches across the entire game lua Mang. Patches . unpatchOwner ( &quot;my-mod&quot; ) When the last patch on a target method is removed, MLua automatically restores the game&#39;s original unpatched code. Discovering Targets ​ Not sure what methods exist in the game assembly? Use Mang.Reflection to explore: lua give Mang. Reflection local targets = Mang. Reflection . patchTargets () for i = 1 , targets. Count do print ( targets : Get (i)) end Function Description Mang.Reflection.types() Lists all registered type names Mang.Reflection.hasType(name) Checks whether a type is registered Mang.Reflection.members(name) Lists instance methods and fields for a type Mang.Reflection.staticMembers(name) Lists static methods and fields for a type Mang.Reflection.patchTargets() Lists all methods currently available for patching Mang.Reflection.resolvePatch(target, argc) Resolves a target name and argument count to a canonical signature Troubleshooting ​ Issue What to check TargetNotFound Check spelling of assembly, namespace, type, and method names, or verify the overload parameter types SignatureMismatch The method uses unsupported types like by-value structs or complex generics Rejected The game host&#39;s security settings blocked patching on this specific method BackendFailed The native inline hook could not be placed Ordering cycle Two patches have conflicting before and after rules"},{"url":"mlua/prelude.html","title":"Prelude | MLua","text":"Prelude ​ The prelude is the set of globals available to every chunk before it runs. The VM opens selected Lua 5.4 libraries: base, table, string, math, coroutine and utf8. It does not open the entire standard library. The tables below show common functions, not every member. Lua 5.4 standard library ​ Table Contents base assert error pcall xpcall select type tostring tonumber ipairs pairs next rawget rawset rawequal rawlen setmetatable getmetatable print string byte char find format gmatch gsub len lower match rep reverse sub upper pack unpack packsize table insert remove move concat sort pack unpack math abs ceil floor sqrt sin cos tan exp log max min random randomseed fmod modf tointeger type huge pi maxinteger mininteger coroutine create resume yield status wrap isyieldable running close utf8 char codepoint codes len offset charpattern os , io , package , debug , load , loadfile , loadstring and dofile are removed from the native environment. The integration installs a restricted require for registered source modules. It is not filesystem or native-library access. Type and class helpers ​ Function Description typeof(value) Declared type name as a string. kindof(value) Kind of the value: class , interface , enum , table , and so on. classof(value) The class table, or nil . instanceof(value, class) Whether the value derives from the given class. implements(value, interface) Whether the value satisfies the registered interface. isenum(value) Whether the value is an enum. typeargs(value) The runtime type arguments of a generic instance. typecheck(value, expected, label) Assert that a value has the expected type. super(self, class, name, ...) Invoke the base implementation of name . Table and list helpers ​ Function Description foreach(t, fn) Call fn for each element. map(t, fn) Build a list of fn results. filter(t, fn) Keep the elements fn accepts. reduce(t, fn, acc) Fold the list into one value. find(t, fn) First element fn accepts, or nil . any(t, fn) / all(t, fn) Whether any or every element passes. count(t, fn) How many elements pass. contains(t, value) / indexof(t, value) Membership and position. keys(t) / values(t) Keys and values of a table. copy(t) / merge(a, b) Shallow copy and merge. range(a, b, step) A numeric range as a list. sum(t) / min(t) / max(t) Aggregates. reverse(t) / slice(t, from, to) Order and sub-list. flatten(t) / unique(t) Nesting and duplicates. String and number helpers ​ Function Description split(str, sep) / join(t, sep) Split and join. trim(str) Remove surrounding whitespace. startswith(str, s) / endswith(str, s) Affix tests. clamp(x, lo, hi) Clamp to a range. lerp(a, b, t) Linear interpolation. round(x) / sign(x) Round and sign. default(value, fallback) value , or fallback when value is nil . Managed modules ​ Managed libraries must be registered and loaded in the script environment. Mang.Reflection is registered by the managed script wrapper. Mang.Patches requires a configured patcher. Module Contents Mang.Patches installed unpatchOwner unpatchTarget unpatchAll Mang.Reflection types hasType members staticMembers constructible patchTargets resolvePatch lua give Mang. Patches give Mang. Reflection print (Mang. Patches . installed ()) print (Mang. Reflection . hasType ( &quot;UnityEngine.Transform&quot; )) See Patching for the patch attributes and the frame, and Class injection for injecting new managed types."},{"url":"mlua/types.html","title":"Types and annotations | MLua","text":"Types and annotations ​ Annotations are optional. They tell the compiler what type a value should be, and are checked before your script runs. Where annotations are allowed ​ lua local count : number = 0 local function Scale (value: number , factor: number ): number return value * factor end function Attach (target: object ): object return target end class Player public health : number = 100 private name : string = &quot;&quot; public function Heal (amount: number ): number self . health = self . health + amount return self . health end end Built-in type names ​ Name Meaning any Any value. Assignable in both directions, never reported. object The root type. Every value is assignable to it. nil The nil value. Assignable to any annotation. boolean true or false . number Integer or float. string String value. table Lua tables. MLua instances use userdata, not ordinary table storage. function Any callable. userdata Native or managed handle. void No return value. Any class, interface or enum name is also a type name. Dotted names resolve through namespaces and modules, for example UnityEngine.Vector3 . Assignability ​ any and unresolved types are compatible with everything. nil is assignable to every annotation. object accepts every value, including table literals. A class is assignable to its base classes and to interfaces it implements. Type parameters are compatible in both directions inside their own generic scope. Everything else must match by kind and by name. lua local function Accept (value: object ) end Accept ( 1 ) Accept ( &quot;text&quot; ) Accept ({}) Accept ( nil ) Inference ​ When a local has an annotation but its initializer is untyped, the annotation wins and is used to resolve the call: lua local function Attach (cube: GameObject ): CubeRotator local rotator : CubeRotator = cube : AddComponent () local resolved : CubeRotator = cube : GetComponent () return resolved end Here cube is a function parameter. CubeRotator must be a declared component class. Both calls receive CubeRotator as the requested type, so the explicit generic argument can be omitted. Type queries ​ lua local isPlayer = instanceof (value, Player) local canDrink = implements (value, IDrink) local typeName = typeof (value) local kindName = kindof (value) local classTable = classof (value) Function Result instanceof true if the value is an instance of the class or a subclass. implements true if the value&#39;s class declares that interface. typeof The declared type name as a string. kindof The kind: class , interface , enum , table , number , and so on. classof The class table itself, or nil for plain values."},{"url":"ru/index.html","title":"MLua","text":"MLua Skip to content MLua Search K Main Navigation MLua Русский English Русский English Appearance MLua Моддинг для игр на Unity Язык MLua Стандартная библиотека (Prelude) Справочник языка MLua"},{"url":"ru/mlua/classes.html","title":"Классы и интерфейсы | MLua","text":"Классы и интерфейсы ​ Классы позволяют объединять данные (поля) и логику (методы) в понятные и удобные типы. Интерфейсы определяют правила и контракты, которым обязаны следовать классы. Вместе они формируют полноценную объектно-ориентированную систему MLua - во время выполнения скрипта всё это быстро работает поверх таблиц и userdata, а ошибки типов отлавливаются компилятором ещё до запуска игры. Если вы раньше программировали на C#, Java или TypeScript, синтаксис покажется вам очень знакомым. Главные отличия: ключевое слово self пишется явно в каждом методе, а вызовы родительских методов используют функцию super . Объявление класса ​ Вот простой пример класса счётчика: lua class Counter public value : number = 0 public function Increment (): number self . value = self . value + 1 return self . value end end Объявление класса создаёт новый именованный тип. Его можно объявить глобально или внутри пространства имён ( namespace ). Тело класса закрывается ключевым словом end . Внутри любого метода self указывает на текущий объект. Члены класса ​ Класс может содержать поля, методы, конструкторы и статические переменные в любых нужных вам сочетаниях: Член класса Пример синтаксиса Что делает Поле public value: number = 0 Переменная экземпляра, создаётся вместе с объектом Метод public function Name(args): ReturnType ... end Функция, вызываемая у объекта через двоеточие: obj:Name() Конструктор public function init(args) ... end Инициализирует объект при создании Статическое поле public static count: number = 0 Принадлежит самому классу: Counter.count Статический метод public static function Create(): Counter ... end Вызывается напрямую у класса: Counter.Create() Модификаторы доступа ​ У каждого поля и метода есть уровень видимости, который помогает писать надёжный код без случайных багов: Модификатор Кому доступен член класса public Доступен отовсюду (используется по умолчанию, если не указан) protected Доступен только внутри объявившего класса и всех его наследников private Доступен строго внутри объявившего класса Наследование ​ Класс наследует базовый класс через двоеточие : BaseName : lua class Base public virtual function Value (): number return 1 end end class Child : Base public override function Value (): number return super ( self , Child, &quot;Value&quot; ) + 1 end end Ключевые слова наследования: Ключевое слово Что означает override Обязательно при замене унаследованного метода родительского класса final Запрещает дочерним классам переопределять этот метод abstract Объявляет сигнатуру метода без тела - наследники обязаны его реализовать abstract class Помечает класс, который нельзя напрямую создать через new Чтобы вызвать реализацию метода из родительского класса, используйте super(self, ТекущийКласс, &quot;ИмяМетода&quot;, аргументы...) . Абстрактные классы ​ Абстрактный класс служит шаблоном для создания других классов: lua abstract class Shape public abstract function Area (): number end class Circle : Shape public radius : number = 1 public override function Area (): number return 3.14159 * self . radius * self . radius end end Создание объектов ​ В MLua есть три взаимозаменяемых способа создать объект и вызвать его конструктор init : lua local a = Counter. new () -- строчный вызов .new() local b = Counter. New () -- заглавный вызов .New() local c = new Counter () -- привычное ключевое слово new, как в C# или Java Все переданные аргументы автоматически направляются в метод init : lua class Person private name : string = &quot;&quot; public function init (name: string ) self . name = name end public function GetName (): string return self . name end end local person = new Person ( &quot;PlayerOne&quot; ) print ( person : GetName ()) -- &quot;PlayerOne&quot; Если у класса нет явного метода init , объект создаётся со всеми полями, заполненными значениями по умолчанию. Интерфейсы ​ Интерфейс задаёт контракт из методов, которые обязан предоставить реализующий его класс. Интерфейсы не хранят состояния - в них нет полей и готового кода. Краткая форма - удобна, когда нужно просто перечислить имена методов: lua interface IValue (Value) interface IDrink (MakeDrink, Refill) Блочная форма - позволяет точно указать типы аргументов и возврата: lua interface IShape public function Area (): number public function Scale (factor: number ) end Реализация интерфейса выполняется через ключевое слово implements : lua class CoffeeCup : Person implements IDrink public function MakeDrink (): string return &quot;espresso&quot; end public function Refill () print ( &quot;Чашка наполнена!&quot; ) end end Класс может реализовывать сколько угодно интерфейсов через запятую: implements IDrink, IValue, IShape . Если вы забудете написать какой-то из объявленных методов, компилятор сразу же сообщит об ошибке. Практический пример ​ Вот как абстрактные классы и интерфейсы работают вместе в реальном коде: lua abstract class Entity implements IShape public abstract function Area (): number public name : string = &quot;entity&quot; end class Box : Entity public width : number = 1 public height : number = 1 public override function Area (): number return self . width * self . height end end local box = new Box () box. width = 4 box. height = 3 print ( &quot;Площадь:&quot; , box : Area ()) -- 12 Что изучить дальше ​ Раздел О чём рассказывается Типы и аннотации Добавление статических типов к переменным и методам Перечисления и дженерики Использование enum и универсальных классов-контейнеров Модули и пространства имён Организация классов в namespaces и импорт модулей Стандартная библиотека Prelude Встроенные функции для строк, таблиц и ООП"},{"url":"ru/mlua/definitions.html","title":"Директивы препроцессора и условная компиляция | MLua","text":"Директивы препроцессора и условная компиляция ​ Директивы препроцессора вычисляются MLua ещё до компиляции скрипта. С их помощью можно легко включать и выключать отдельные функции мода, поддерживать разные версии игры или отделять отладочный код от релизного. Объявление значений ​ Вы можете объявлять флаги прямо в начале файлов с помощью директивы #define : lua # define SHOW_COUNTER true # define LIMIT 10 # define MOD_NAME &quot;ExampleMod&quot; # ifdef SHOW_COUNTER print ( &quot;Счётчик включён!&quot; ) # endif Директива #define NAME сама по себе задаёт значение true . Также можно указывать логические значения, числа или строки в двойных кавычках. Имена директив чувствительны к регистру. Доступные директивы ​ Директива Что делает #define NAME value Задаёт флаг или значение в текущей ветке #undef NAME Удаляет ранее объявленный флаг #ifdef NAME Проверяет, был ли объявлен флаг #ifndef NAME Проверяет, что флаг не объявлен #if NAME Проверяет истинность значения флага #ifnot NAME Проверяет ложность значения флага #elif NAME , #elseif NAME Альтернативное условие #else Ветка по умолчанию, если условия выше ложны #endif , #end Закрывает условный блок Условия принимают имя флага, перед которым может стоять знак ! или not . Это инструмент условного включения кода - сложные арифметические выражения вроде #if VERSION &gt;= 2 не поддерживаются. lua # define FEATURE false # ifdef FEATURE print ( &quot;FEATURE объявлена&quot; ) # endif #if FEATURE print ( &quot;Эта строка не попадет в скомпилированный код&quot; ) #else print ( &quot;FEATURE выключена&quot; ) # endif # undef FEATURE Неактивные строки в коде заменяются пустыми строками, благодаря чему номера строк в ошибках компилятора всегда точно совпадают с вашим файлом. Флаги, передаваемые игрой ​ Игра может передавать глобальные флаги в окружение модов через таблицу DEFINE . Проверить их наличие можно с помощью функции defined(name) : lua if defined ( &quot;GAME_VERSION&quot; ) then print ( &quot;Версия игры:&quot; , DEFINE[ &quot;GAME_VERSION&quot; ]) end"},{"url":"ru/mlua/diagnostics.html","title":"Диагностика и ошибки компилятора | MLua","text":"Диагностика и ошибки компилятора ​ Каждое диагностическое сообщение содержит уникальный код ошибки, позицию в исходном коде и текстовое описание. Префикс кода указывает этап конвейера компиляции, на котором была обнаружена проблема. Диапазоны кодов ​ Диапазон Этап Значение MLUA1xxx Лексер Ошибки токенов: незакрытые строки, некорректные числа, недопустимые escape-последовательности MLUA3xxx Парсер Грамматические ошибки: пропущенный end , неожиданный токен, неверный синтаксис MLUA42xx Доступ Нарушения видимости private и protected членов MLUA43xx Объявления Ошибки override , final , abstract или реализации интерфейсов MLUA44xx Типы Неизвестные члены, несоответствие типов аргументов, недопустимые операторы Ошибки всегда выводятся, начиная с самого раннего упавшего этапа. Например, скрипт с лексической ошибкой даже не начинает парситься или проверяться по типам, поскольку последующие стадии требуют успешного прохождения предыдущих. Часто встречающиеся коды ​ Код Сообщение Причина MLUA3001 unexpected token after chunk body Лишний end или блок, закрытый дважды MLUA3013 unexpected token in type body Инструкция, помещённая прямо в тело класса или интерфейса MLUA3017 expected an expression Ключевое слово объявления использовано там, где ожидалось значение MLUA4206 member is private to a class Чтение закрытого члена извне класса MLUA4207 member is protected in a class Чтение защищённого члена вне иерархии классов MLUA4403 operator applied to the wrong type Например, оператор длины # применён к числу MLUA4404 cannot assign one type to another Тип значения не соответствует аннотации переменной MLUA4410 type has no member named ... Опечатка или обращение к необъявленному полю / методу MLUA4411 argument expects one type but received another Переданный аргумент не соответствует объявленному типу параметра MLUA4412 enum member is read only Попытка изменить значение элемента перечисления Формат диагностического сообщения ​ Сообщения об ошибках имеют постоянный формат: =test:24:52 MLUA4206: secret is private to Base Часть Значение =test Имя чанка (файла) 24:52 Номер строки и колонки токена MLUA4206 Код ошибки (остаток) Понятное объяснение ошибки Этот формат стабилен и удобен для парсинга редакторами и инструментами сборки. Уровень серьёзности (Severity) ​ У компилятора есть только один уровень критичности: ошибка (error) . Чанк хотя бы с одной диагностической ошибкой не запустится в игре - опечатка в имени поля, неверный override или несоответствие типов будут пойманы до того, как код начнёт исполняться, что исключает неожиданные падения игры посреди игровой сессии. Предупреждений (warnings) и директив подавления ошибок нет. Если вам нужно отключить строгие проверки для конкретного значения, объявите его с типом any или object - это делает ослабление типизации явным в самом коде. Строгий анализ и выполнение с проверками в рантайме ​ Строгий режим, используемый функцией AnalyzeSource , выдаёт ошибки для всех несоответствий типов и нарушений доступа. Режим RuntimeChecked , используемый во время обычного запуска, сохраняет синтаксические ошибки и проверки типов, но позволяет динамические поля через метатаблицы."},{"url":"ru/mlua/environment.html","title":"MLua и игра | MLua","text":"MLua и игра ​ Кто запускает скрипт? ​ Разработчик игры встраивает MangLua в свой проект и определяет доступные скрипты и API. Вы, как автор мода, пишете код на MLua для взаимодействия с этим предоставленным API. Запущенная игра часто называется хост-приложением . Три уровня возможностей ​ Уровень Что предоставляет Чего не предоставляет Виртуальная машина Lua Значения, функции, таблицы, корутины и базовые библиотеки Доступ ко всем типам игры Язык MLua и Prelude Классы, модификаторы доступа, перечисления, дженерики и вспомогательные функции Автоматические права на патчинг методов или создание компонентов Интеграция с игрой Зарегистрированные управляемые типы, модули API, привязка компонентов и бэкенд патчинга Гарантию работы всех возможностей C# или произвольных соглашений вызова Скрипт может использовать ту или иную возможность только тогда, когда присутствуют соответствующие уровни. Полный пример без неявных объектов ​ Для этого примера игра должна предоставить доступ к GameObject и PrimitiveType из Unity API: lua give UnityEngine local cube = GameObject. CreatePrimitive (PrimitiveType. Cube ) cube. name = &quot;MLua cube&quot; print (cube. name ) Здесь cube - локальная переменная со ссылкой на объект, возвращённый методом CreatePrimitive . Никаких неявных глобальных переменных вроде host в рантайме не предполагается. Доступность функций ​ Перед написанием мода изучите список открытых типов игры и поддерживаемые возможности. Подробнее смотрите в разделах Работа с Unity и игровым API , Инъекция классов и Патчинг методов ."},{"url":"ru/mlua/generics.html","title":"Перечисления и дженерики | MLua","text":"Перечисления и дженерики ​ Перечисления (Enums) ​ Перечисления представляют собой неизменяемые наборы именованных значений: lua enum Element { Fire, Water = 5 , Air } assert (Element. Fire == 0 ) assert (Element. Water == 5 ) assert (Element. Air == 6 ) assert (Element. name ( 5 ) == &quot;Water&quot; ) assert ( # Element == 3 ) Элементы enum хранят обычные базовые числовые значения. Для обратного поиска по числу используйте метод Element.name(value) . Выражение Результат Element.name(value) Имя первого зарегистрированного элемента для значения, либо nil Element.value(name) Значение по имени элемента, либо nil Element.has(name) Существует ли элемент с таким именем Element.names() Упорядоченный список имён элементов Element.values() Упорядоченный список значений элементов #Element Количество элементов в перечислении kindof(Element) &quot;enum&quot; isenum(Element) true Попытка записи в поля enum приводит к ошибке во время компиляции или в рантайме. Обобщённые классы (Generics) ​ lua class Box &lt;T&gt; private item = nil public function init (value) self . item = value end public function Get () return self . item end public function Argument () return typeargs ( self ). T end end local box = new Box &lt;Element&gt; (Element. Water ) assert ( box : Get () == 5 ) assert ( box : Argument () == Element) assert ( typeof (box) == &quot;Box&lt;Element&gt;&quot; ) assert ( instanceof (box, Box)) Специализация выполняется рантаймом MLua. Повторная специализация с теми же аргументами типа автоматически кэшируется. Обобщённые функции и компоненты ​ lua local function AddComponent &lt; T : Component &gt;(target: object ): object return target : AddComponent &lt;T&gt; () end Для работы этой функции игра должна предоставить доступ к Component и соответствующему API компонентов. Аргумент типа передаётся напрямую в вызываемый управляемый метод. Рантайм автоматически выполняет вывод типов и проверку ограничений."},{"url":"ru/mlua/injection.html","title":"Инъекция классов в Unity | MLua","text":"Инъекция классов в Unity ​ Хотите, чтобы ваш скрипт на MLua работал как полноценный компонент MonoBehaviour в Unity? Именно для этого предназначена инъекция классов. Обычный class - это просто скриптовый объект. А инъецированный класс становится настоящим компонентом Unity, прикрепляется к GameObject и получает стандартные события жизненного цикла движка, такие как Update , Start , Awake и FixedUpdate . Полный рабочий пример ​ Вот как написать компонент, который плавно вращает объект каждый кадр: lua give UnityEngine @[ Component ( &quot;Spinner&quot; )] class Spinner : MonoBehaviour public speed = 90 public function Update () self . transform . Rotate ( 0 , self . speed * Time. deltaTime , 0 ) end end -- Создаём куб и прикрепляем наш пользовательский компонент local cube = GameObject. CreatePrimitive (PrimitiveType. Cube ) local spinner : Spinner = cube : AddComponent &lt;Spinner&gt; () -- Настраиваем его скорость spinner. speed = 45 -- Проверяем, что компонент действительно прикреплён assert ( cube : GetComponent &lt;Spinner&gt; () == spinner) В этом примере: cube - созданный в мире игровой объект ( GameObject ). spinner - экземпляр вашего скриптового компонента. Внутри методов self указывает на сам компонент. self.gameObject возвращает родительский объект GameObject . self.transform даёт прямой доступ к его Transform . Атрибут @[Component] ​ Атрибут @[Component(&quot;Spinner&quot;)] задаёт псевдоним компонента. Он регистрирует класс в системе компонентов MangLua, чтобы Unity мог создавать его и передавать ему события кадров и физики. Добавление и поиск компонентов ​ Прикрепить компонент к объекту можно двумя способами - через явный дженерик или через вывод типа из локальной переменной: lua -- Явный синтаксис дженерика local spinner : Spinner = cube : AddComponent &lt;Spinner&gt; () -- Автоматический вывод типа из аннотации переменной local spinner : Spinner = cube : AddComponent () -- Поиск уже существующего компонента на объекте local found : Spinner = cube : GetComponent &lt;Spinner&gt; () assert (found == spinner) Метод GetComponent ищет уже существующий компонент на данном GameObject - если компонент ещё не был добавлен, метод вернёт nil . Наследование и базовые компоненты ​ Вы можете строить удобные иерархии компонентов с помощью обычного наследования и абстрактных классов: lua @[ Component ( &quot;BaseMotor&quot; )] abstract class BaseMotor : MonoBehaviour public ticks = 0 public function Update () self . ticks = self . ticks + 1 end end @[ Component ( &quot;FastMotor&quot; )] class FastMotor : BaseMotor public function Start () print ( &quot;FastMotor успешно запущен!&quot; ) end end -- Прикрепляем конкретный класс-наследник local motor : FastMotor = cube : AddComponent &lt;FastMotor&gt; () -- Ищем его по типу базового класса local base : BaseMotor = cube : GetComponent &lt;BaseMotor&gt; () assert (base == motor) Обратите внимание: abstract class нельзя прикрепить к объекту напрямую, создавать можно только его конкретные подклассы. События жизненного цикла Unity ​ Компоненты MLua получают все стандартные вызовы Unity. Метод init является конструктором самого скрипта, но для работы с объектом сцены ( gameObject или transform ) рекомендуется использовать Awake или Start : Метод Когда вызывается движком Unity Awake() Вызывается сразу при создании и прикреплении компонента к объекту сцены OnEnable() Вызывается при активации компонента или родительского объекта Start() Вызывается один раз перед самым первым обновлением кадра Update() Вызывается каждый кадр - идеально для движения, таймеров и чтения ввода FixedUpdate() Вызывается с фиксированным шагом физики - для расчётов с Rigidbody LateUpdate() Вызывается в конце каждого кадра после всех Update - отлично подходит для камер OnDisable() Вызывается при отключении компонента или родительского объекта OnDestroy() Вызывается непосредственно перед полным уничтожением компонента или объекта Решение типичных вопросов ​ Ситуация Что проверить MonoBehaviour не найден Убедитесь, что в самом верху скрипта написана строка give UnityEngine Метод Update не вызывается Проверьте регистр букв: имена методов Unity чувствительны к регистру ( Update , а не update ) Ошибка при добавлении абстрактного класса Нельзя добавить abstract class напрямую - добавьте конкретный класс-наследник GetComponent возвращает nil Проверьте, что компонент был добавлен на этот объект через AddComponent , или что вы ищете его на правильном GameObject"},{"url":"ru/mlua/language.html","title":"Справочник языка MLua | MLua","text":"Справочник языка MLua ​ MLua является строгим надмножеством Lua 5.4, поэтому любой корректный скрипт на Lua 5.4 работает в MLua без каких-либо изменений. Всё стандартное поведение Lua сохранено: комментарии, строки, числа, операторы, управляющие конструкции, замыкания, vararg, множественный возврат, метатаблицы, корутины и goto . Все описанные на этой странице возможности либо напрямую унаследованы из Lua, либо являются чистыми расширениями MLua. Это руководство предполагает знакомство хотя бы с одним статически типизированным языком (C#, TypeScript или Java). Специфичные для Lua концепции вроде метатаблиц здесь не рассматриваются - подробности можно найти в справочном руководстве Lua . Чанки ​ Чанк (chunk) - это последовательность инструкций. Точки с запятой между инструкциями не требуются, но одиночный символ ; принимается как пустая инструкция. lua local message = &quot;hello&quot; print (message) Комментарии ​ Однострочные и многострочные комментарии соответствуют стандартному синтаксису Lua: lua -- Однострочный комментарий --[[ Многострочный комментарий, занимающий несколько строк ]] Значения и типы данных ​ MLua использует те же восемь базовых типов значений, что и Lua: Тип Описание nil Отсутствие значения boolean true или false number Число (целое или с плавающей точкой) string Неизменяемая последовательность байт table Ассоциативный массив, основа для всех объектов function Функция как объект первого класса userdata Объект, управляемый хостом (например, компонент Unity) thread Корутина MLua не вводит новых рантайм-типов. Классы, интерфейсы и перечисления представляют собой слой времени компиляции поверх таблиц и userdata. Переменные ​ Локальные, глобальные, константные и закрываемые переменные следуют синтаксису Lua 5.4: lua local count = 0 local a, b, c = 1 , 2 -- c равен nil local frozen &lt;const&gt; = 10 -- константа времени компиляции local handle &lt;close&gt; = open () -- автоматически закрывается при выходе из области видимости globalValue = 1 -- глобальное присваивание Любая локальная переменная может содержать аннотацию типа. Компилятор проверяет её перед запуском скрипта: lua local speed : number = 90 local owner : Player = FindPlayer () → Подробнее о системе типов, выводе и совместимости читайте в разделе Типы и аннотации . Операторы ​ MLua сохраняет все операторы Lua 5.4 и добавляет запросы типов и безопасный доступ: Группа Операторы Арифметика + - * / // % ^ унарный - Побитовые &amp; | ~ &lt;&lt; &gt;&gt; унарный ~ Сравнение == ~= &lt; &lt;= &gt; &gt;= Логика and or not Строка / размер .. # Проверка типов instanceof(v, C) implements(v, I) typeof(v) kindof(v) classof(v) Безопасный доступ ?. ?? Поддерживаются составные присваивания ( += , -= , *= и другие). lua local label = enemy?. name ?? &quot;unknown&quot; -- безопасный доступ с fallback-значением local isEnemy = instanceof (value, Enemy) -- проверка типа в рантайме local typeName = typeof (value) -- имя типа в виде строки Управление потоком выполнения ​ В MLua доступны все управляющие конструкции Lua 5.4, а также ключевое слово continue для перехода к следующей итерации цикла: lua -- Условие if value &gt; 10 then print ( &quot;high&quot; ) elseif value &gt; 0 then print ( &quot;low&quot; ) else print ( &quot;zero&quot; ) end -- Цикл while while active do step () end -- Цикл repeat-until repeat step () until done -- Числовой цикл for с continue for index = 1 , 10 , 2 do if index == 5 then continue end print (index) end -- Обобщённый for for key, value in pairs (source) do print (key, value) end -- Явная область видимости do local scoped = 1 end Управление циклами: Инструкция Поведение break Прерывает выполнение текущего цикла continue Переходит к следующей итерации (только в MLua) goto label / ::label:: Безусловный переход, как в Lua 5.4 Функции ​ Функции являются значениями первого класса: lua -- Локальная именованная функция local function add (a, b) return a + b end -- Глобальная функция с varargs function Global (a, ...) return a, select ( &quot;#&quot; , ... ) end -- Функциональное выражение local handler = function (event) end -- Метод с неявным self local target = {} function target : Method (value) return self , value end Параметры и возвращаемые значения поддерживают аннотации типов: lua local function Distance (from: Vector3 , to: Vector3 ): number return (to - from). magnitude end Сводка синтаксических конструкций ​ Инструкция Форма записи Локальная переменная local a, b = 1, 2 Локальная с типом local a: number = 1 Присваивание a.b, c = 1, 2 Составное присваивание a += 1 a -= 1 … Вызов функции f() obj:m() Блок видимости do ... end Условие if ... then ... elseif ... else ... end Цикл while while ... do ... end Цикл repeat repeat ... until ... Числовой for for i = start, stop, step do ... end Обобщённый for for k, v in iter do ... end Переходы break continue goto return Функция function f() end local function f() end Объявление типов class interface enum Пространство имён namespace Name ... end Импорт API give Name import Name Атрибут @[Name(args)] перед объявлением Куда двигаться дальше ​ Тема Описание Типы и аннотации Базовые типы, вывод типов и проверка совместимости Классы и интерфейсы Наследование, конструкторы, модификаторы доступа Стандартная библиотека (Prelude) Набор функций, доступных каждому скрипту Модули give , пространства имён и атрибуты"},{"url":"ru/mlua/managed-api.html","title":"Работа с Unity и игровым API | MLua","text":"Работа с Unity и игровым API ​ Когда вы создаёте моды на MLua, вы пишете не изолированные скрипты - вам открыт полный доступ к движку Unity и внутренним системам самой игры. Вы можете спавнить объекты на сцене, перемещать их, работать с физикой, управлять камерой и вызывать игровые функции напрямую из Lua. Подключение Unity ​ Чтобы использовать типы Unity в своём скрипте, просто запросите пространство имён с помощью give : lua give UnityEngine local player = GameObject. Find ( &quot;Player&quot; ) if player ~= nil then print ( &quot;Игрок найден на позиции: &quot; .. tostring (player. transform . position )) end После этого стандартные типы Unity, такие как GameObject , Transform , Vector3 , Time и Mathf , становятся полностью доступны. Работа с игровыми объектами (GameObject) ​ Находить, создавать и изменять объекты в мире можно очень просто: lua give UnityEngine -- Найти существующий объект на сцене по имени local boss = GameObject. Find ( &quot;BossEnemy&quot; ) -- Найти объект по тегу local spawnPoint = GameObject. FindWithTag ( &quot;Respawn&quot; ) -- Создать новый примитивный объект в мире local cube = GameObject. CreatePrimitive (PrimitiveType. Cube ) cube. name = &quot;MyModCube&quot; -- Переместить его в нужные координаты cube. transform . position = Vector3 ( 0 , 10 , 0 ) Получение и добавление компонентов ​ В Unity каждый GameObject состоит из компонентов. Вы можете искать существующие компоненты на объекте или прикреплять новые: lua give UnityEngine local light = cube : GetComponent &lt;Light&gt; () if light == nil then -- Добавляем компонент, если его ещё нет light = cube : AddComponent &lt;Light&gt; () end -- Настраиваем свойства компонента light. color = Color. red light. intensity = 5.0 Вы также можете прикреплять свои собственные классы MLua, помеченные атрибутом @[Component] - подробнее об этом читайте в разделе Инъекция классов в Unity . Чтение и запись свойств ​ Свойства и поля объектов Unity читаются и меняются как обычные поля таблиц в Lua: lua give UnityEngine local player = GameObject. Find ( &quot;Player&quot; ) local transform = player. transform -- Читаем текущую позицию local currentPos = transform. position print ( &quot;Координаты:&quot; , currentPos. x , currentPos. y , currentPos. z ) -- Сдвигаем игрока вперёд transform. position = currentPos + Vector3 ( 0 , 0 , 5 ) -- Получаем дельту времени кадра local delta = Time. deltaTime Вызов методов ​ Методы компонентов и объектов Unity вызываются через стандартное двоеточие Lua :Method() : lua give UnityEngine local rb = player : GetComponent &lt;Rigidbody&gt; () if rb ~= nil then -- Вызываем метод экземпляра rb : AddForce (Vector3. up * 10 , ForceMode. Impulse ) end -- Вызываем статический метод local dist = Vector3. Distance (player. transform . position , cube. transform . position ) print ( &quot;Дистанция до куба:&quot; , dist) Векторы и математика ​ Векторы и математические функции Unity работают прямо из коробки: lua give UnityEngine -- Создаём векторы local spawn = Vector3 ( 10 , 0 , 10 ) local offset = Vector3 ( 0 , 2 , 0 ) local target = spawn + offset -- Операции с векторами local direction = (target - spawn). normalized local distance = Vector3. Distance (spawn, target) -- Цвета local highlight = Color ( 1.0 , 0.5 , 0.0 , 1.0 ) Списки и коллекции C# ​ Когда игра возвращает список ( List ) или массив C#, вы можете узнать его длину и перебрать элементы через методы коллекции: lua local inventory = player : GetComponent &lt;Inventory&gt; () local items = inventory. Items -- Количество предметов print ( &quot;Количество предметов в инвентаре:&quot; , items. Count ) -- Перебор элементов по индексу for i = 0 , items. Count - 1 do local item = items : Get (i) print ( &quot;Предмет:&quot; , item. name ) end Собственные пространства имён игры ​ Помимо движка Unity, игры часто открывают собственные пространства имён с геймплейной логикой. Они подключаются точно так же: lua give Game. Combat give Game. Inventory local weapon = WeaponDatabase. GetWeapon ( &quot;Excalibur&quot; ) print ( &quot;Урон оружия:&quot; , weapon. BaseDamage ) Если какое-то пространство имён или тип не поддерживаются игрой, компилятор MLua сразу покажет понятную ошибку ещё до старта мода."},{"url":"ru/mlua/modules.html","title":"Модули и атрибуты | MLua","text":"Модули и атрибуты ​ Загрузка зарегистрированного модуля ​ lua give UnityEngine give Mang. Reflection Инструкция give запрашивает модуль, зарегистрированный в окружении вашего скрипта. Модуль сам определяет, какие типы и методы он предоставляет. Исходный модуль выполняется и кэшируется после успешной загрузки. При циклическом импорте или отсутствии модуля выдаётся ошибка. Команда give UnityEngine открывает доступ к типам Unity, таким как GameObject , Transform и Vector3 . Подробнее о работе с объектами Unity читайте в разделе Работа с Unity и игровым API . Для модулей, написанных как стандартные файлы Lua, можно использовать специальную функцию require . Для создания локального псевдонима загрузите модуль и сохраните нужный тип в локальную переменную: lua give UnityEngine local Vec = UnityEngine. Vector3 local position = Vec ( 0 , 1 , 0 ) Пространства имён ​ lua namespace Game. Combat class Weapon public damage = 10 end end local weapon = new Game. Combat . Weapon () Пространство имён группирует объявления по заданному пути. Глобальные переменные чанка и импортированные значения остаются общими внутри одного скриптового окружения. Атрибуты ​ Атрибут связывает метаданные со следующим за ним объявлением: lua @[ Component ( &quot;Spinner&quot; )] class Spinner : MonoBehaviour public speed = 90 end Форма записи: @[Имя] или @[Имя(аргументы)] Перед одним объявлением можно указать несколько атрибутов Атрибуты патчей принимают целевой метод и параметры, например owner = &quot;my-mod&quot; Встроенные обработчики ( Component , Prefix , Postfix , Replace ) настраивают интеграцию с Unity и нативный перехват методов API позволяет читать типизированные атрибуты и регистрировать собственные обработчики. Несколько файлов ​ Файлы компилируются как отдельные чанки. Чтобы использовать объявления из другого файла, убедитесь, что этот файл был загружен или зарегистрирован как модуль до первого обращения к его типам. Сохраняйте имена модов, чанков и пространств имён компонентов стабильными при перезагрузках, чтобы избегать конфликтов с другими модами."},{"url":"ru/mlua/patching.html","title":"Патчинг методов | MLua","text":"Патчинг методов ​ Инъекция классов позволяет добавлять в игру совершенно новое поведение. Но что, если вы хотите изменить код, который уже скомпилирован в саму игру? Именно для этого и нужен патчинг. MLua умеет перехватывать (хукать) методы прямо во время выполнения через нативный бэкенд деторов - по смыслу это похоже на популярный Harmony, но встроено прямо в синтаксис языка через удобные атрибуты на обычных функциях Lua. Каждый обработчик патча принимает ровно один аргумент - frame . Считайте, что frame - это живой контекст вызова функции ( context ). Он даёт прямой доступ ко всему, что происходит в данном вызове: входящим аргументам, возвращаемому значению, текущей стадии выполнения, а также ячейке ( frame.State ) для передачи своих данных между стадиями одного и того же перехватчика. Объявление патча ​ Команда give Mang.Patches открывает доступ к функциям управления патчами. Чтобы пропатчить метод, объявите атрибут прямо над локальной функцией. Атрибут указывает целевой метод игры, количество аргументов (для выбора нужной перегрузки) и дополнительные настройки: lua give Mang. Patches @[ Prefix ( &quot;Assembly-CSharp::PatchExample.TakeDamage&quot; , 1 , owner = &quot;my-mod&quot; )] local function BlockBigHits (frame) if frame. Integer0 &gt; 100 then frame. Integer0 = 0 end end Разберём это объявление: Имя атрибута ( Prefix , Postfix , Replace , Around , …) - это вид перехвата, определяющий, когда именно сработает ваш хук относительно оригинального метода игры. Строка цели - полное имя метода в формате Сборка::ПространствоИмён.Тип.Метод . Число сразу после цели - количество аргументов метода, помогающее отличить нужную перегрузку. Все параметры после числа - именованные настройки ключ = значение , например owner = &quot;my-mod&quot; . Если имя метода уникально, количество аргументов можно не указывать, а владельца мода можно написать без кавычек: lua @[ Prefix ( &quot;Assembly-CSharp::PatchExample.TakeDamage&quot; , 1 , CoolMod)] @[ Prefix ( &quot;Assembly-CSharp::PatchExample.Reload&quot; , CoolMod)] @[ Prefix (PatchExample. Reload , CoolMod)] Любой позиционный аргумент, который не является числом или опцией с = , читается как имя владельца ( owner ). Записи CoolMod и owner = &quot;CoolMod&quot; делают одно и то же. Кавычки нужны, только если в имени есть пробелы или запятые. Если у метода нет перегрузок, число аргументов можно опустить. Целевой метод можно писать даже без кавычек через точку (например, PatchExample.Reload ), если такое имя однозначно находится среди загруженных сборок. Функцию-обработчик всегда объявляйте сразу под атрибутом в виде local function . Виды патчей ​ Атрибут Когда запускается @[Prefix] Срабатывает до оригинального метода. Идеально подходит для проверки или подмены входящих аргументов. @[Postfix] Срабатывает сразу после успешного завершения оригинального метода. Позволяет прочитать или изменить результат. @[Replace] Срабатывает вместо оригинального метода. Тело оригинального метода игры пропускается целиком. @[Around] Оборачивает оригинальный метод - запускается один раз до него и один раз после него. @[Finalizer] Срабатывает на этапе выхода из метода даже при возникновении исключений. @[Patch] Синоним для @[Prefix] (через параметр kind = &quot;Postfix&quot; можно сменить тип). Если несколько модов патчат один и тот же метод, они объединяются в аккуратную цепочку вызовов: сначала выполняются все префиксы, затем оригинальный метод (если его не заменили), затем все постфиксы и в конце финализаторы. Что такое Frame (контекст функции) ​ Аргумент frame представляет собой контекст вызова ( context ) целевого метода. Обращаясь к слотам frame , вы читаете или записываете реальные регистры процессора и ячейки стека, с которыми работает игра: Слот фрейма Что означает в контексте вызова frame.Integer0 , frame.Integer1 , … Входящие целочисленные аргументы и указатели на объекты (регистры RDX, R8, R9 и др.) frame.Float0 , frame.Float1 , … Входящие аргументы с плавающей точкой (регистры XMM) frame.ReturnInteger Основной слот возвращаемого целого числа, флага, enum или указателя на объект frame.ReturnInteger1 Дополнительный целочисленный регистр возврата для составных структур или 128-битных значений frame.ReturnFloat , frame.ReturnFloat1..3 Слоты возврата для дробных чисел и векторных структур (Vector2, Vector3, Vector4, Quaternion) frame.ReturnVector , frame.ReturnVector1..3 Слоты возврата векторных и SIMD значений frame.IndirectResult Указатель на буфер вызывающей стороны для возврата больших структур frame.Stage 0 - на этапе входа перед оригиналом, 1 - на этапе выхода после него frame.State Ячейка для хранения ваших промежуточных данных между стадиями 0 и 1 Как стандартные типы C# отображаются во фрейм: Тип параметра или возврата в C# Соответствующий слот фрейма int , uint , long , ulong , byte , bool , char , enums frame.IntegerN / frame.ReturnInteger float , double frame.FloatN / frame.ReturnFloat Структуры и векторы ( Vector2 , Vector3 , Vector4 , Quaternion ) frame.ReturnFloat , frame.ReturnFloat1..3 или frame.IndirectResult Ссылочные типы: string , object , массивы, классы Передаются как нативный указатель в frame.IntegerN Методы экземпляра (с this ) Поддерживаются: this занимает frame.Integer0 , а первый аргумент становится Integer1 frame.State в начале каждого вызова равен 0 . Он создан специально для того, чтобы обработчик @[Around] мог легко передать вычисленное значение со стадии &quot;до вызова&quot; на стадию &quot;после вызова&quot;. Префиксы (Prefix) ​ Префикс выполняется до оригинального метода. Изменяя значение в слоте аргумента, вы заставляете оригинальный метод игры увидеть уже ваше новое значение: lua @[ Prefix ( &quot;Assembly-CSharp::PatchExample.Heal&quot; , 1 , owner = &quot;my-mod&quot; )] local function DoubleHealing (frame) frame. Integer0 = frame. Integer0 * 2 end Постфиксы (Postfix) ​ Постфикс выполняется сразу после оригинального метода. Вы можете проверить результат работы метода и скорректировать его: lua @[ Postfix ( &quot;Assembly-CSharp::PatchExample.GetScore&quot; , 0 , owner = &quot;my-mod&quot; )] local function AddBonus (frame) frame. ReturnInteger = frame. ReturnInteger + 10 end Полная замена (Replace) ​ Замена полностью подавляет оригинальный метод игры. Код игры вообще не вызывается, а ваша функция полностью отвечает за формирование результата: lua @[ Replace ( &quot;Assembly-CSharp::PatchExample.GetPrice&quot; , 0 , owner = &quot;my-mod&quot; )] local function AlwaysFree (frame) frame. ReturnInteger = 0 end Оборачивание (Around) и пропуск оригинального метода ​ Хук @[Around] вызывается дважды за один вызов: сначала на стадии frame.Stage == 0 (до оригинального метода), а затем на стадии frame.Stage == 1 (после него). С помощью frame.State можно передавать значения между ними: lua @[ Around ( &quot;Assembly-CSharp::PatchExample.TakeDamage&quot; , 1 , owner = &quot;my-mod&quot; )] local function ClampDamage (frame) if frame. Stage == 0 then frame. State = frame. Integer0 if frame. Integer0 &gt; 50 then frame. Integer0 = 50 end else print ( &quot;урон был&quot; , frame. State , &quot;стал&quot; , frame. ReturnInteger ) end end Если на стадии входа ( frame.Stage == 0 ) вернуть из функции число 1 , MLua полностью пропустит оригинальный метод: lua @[ Around ( &quot;Assembly-CSharp::PatchExample.Buy&quot; , 1 , owner = &quot;my-mod&quot; )] local function FreePurchases (frame) if frame. Stage == 0 then frame. ReturnInteger = 1 return 1 end end Когда на один метод назначено несколько хуков @[Around] , они вкладываются друг в друга как матрёшка: вход происходит по порядку, а выход - в строго обратном порядке. Финализаторы (Finalizer) ​ Финализатор срабатывает на этапе выхода из метода, обеспечивая гарантированную очистку ресурсов: lua @[ Finalizer ( &quot;Assembly-CSharp::PatchExample.AddXp&quot; , 1 , owner = &quot;my-mod&quot; )] local function ObserveCompletion (frame) assert (frame. Stage == 1 ) print ( &quot;результат начисления опыта:&quot; , frame. ReturnInteger ) end Разрешение перегрузок методов ​ Если у метода несколько перегрузок с разным набором типов, укажите типы аргументов в круглых скобках прямо в строке цели. Стандартные псевдонимы C# ( int , float , string и т.д.) распознаются автоматически: lua @[ Prefix ( &quot;Assembly-CSharp::PatchExample.Select(System.Int32)&quot; , owner = &quot;my-mod&quot; )] local function SelectInt (frame) frame. Integer0 = frame. Integer0 * 2 end Параметры атрибутов ​ Опция Описание owner = &quot;...&quot; Идентификатор владельца (мода) - критически важен для безопасного удаления патчей при перезагрузке priority = n Управляет порядком вызова среди нескольких хуков на один метод args = n , arity = n Явное указание количества аргументов вместо позиционного числа before = &quot;a, b&quot; Гарантирует запуск вашего хука до указанных модов after = &quot;a, b&quot; Гарантирует запуск вашего хука после указанных модов kind = &quot;Postfix&quot; Задаёт вид перехвата при использовании общего атрибута @[Patch] Всегда указывайте owner явно, чтобы ваши патчи можно было корректно обновить или снять при перезагрузке скриптов. Управление установленными патчами ​ Модуль Mang.Patches даёт полный контроль над активными перехватами: Функция Что делает Mang.Patches.installed() Возвращает количество активных в игре патчей Mang.Patches.unpatchOwner(owner) Удаляет все патчи, зарегистрированные конкретным модом Mang.Patches.unpatchTarget(target) Снимает все патчи с конкретного метода Mang.Patches.unpatchAll() Полностью очищает все патчи во всей игре lua Mang. Patches . unpatchOwner ( &quot;my-mod&quot; ) Как только с метода снимается последний патч, MLua моментально и чисто восстанавливает оригинальный нативный машинный код игры. Исследование доступных методов в игре ​ Если вы не знаете точных имён методов игры, модуль Mang.Reflection позволяет быстро просканировать доступные цели: lua give Mang. Reflection local targets = Mang. Reflection . patchTargets () for i = 1 , targets. Count do print ( targets : Get (i)) end Функция Описание Mang.Reflection.types() Возвращает имена всех зарегистрированных типов Mang.Reflection.hasType(name) Проверяет наличие типа в игре Mang.Reflection.members(name) Список методов и полей экземпляра для типа Mang.Reflection.staticMembers(name) Список статических методов и полей для типа Mang.Reflection.patchTargets() Список всех методов, открытых для патчинга Mang.Reflection.resolvePatch(target, argc) Находит точную каноническую сигнатуру метода Диагностика проблем при установке патчей ​ Ошибка Что проверить TargetNotFound Опечатка в сборке, пространстве имён, классе или имени метода, либо неправильно указаны типы перегрузки SignatureMismatch Метод использует неподдерживаемые структуры по значению или слишком сложные типы Rejected Разработчик игры запретил патчинг данного метода в настройках проекта BackendFailed Не удалось установить нативный инлайн-хук в память процесса Ordering cycle Циклическая зависимость между правилами before и after у разных модов"},{"url":"ru/mlua/prelude.html","title":"Стандартная библиотека (Prelude) | MLua","text":"Стандартная библиотека (Prelude) ​ Prelude - это набор глобальных функций и таблиц, доступных каждому скрипту перед началом выполнения. Виртуальная машина открывает библиотеки base, table, string, math, coroutine и utf8. Стандартные библиотеки Lua 5.4 ​ Таблица Содержимое base assert error pcall xpcall select type tostring tonumber ipairs pairs next rawget rawset rawequal rawlen setmetatable getmetatable print string byte char find format gmatch gsub len lower match rep reverse sub upper pack unpack packsize table insert remove move concat sort pack unpack math abs ceil floor sqrt sin cos tan exp log max min random randomseed fmod modf tointeger type huge pi maxinteger mininteger coroutine create resume yield status wrap isyieldable running close utf8 char codepoint codes len offset charpattern Функции os , io , package , debug , load , loadfile , loadstring и dofile удалены из нативного окружения в целях безопасности. Вместо этого предоставляется безопасный require только для зарегистрированных модулей скрипта без прямого доступа к файловой системе или внешним библиотекам. Вспомогательные функции для типов и классов ​ Функция Описание typeof(value) Имя объявленного типа в виде строки kindof(value) Категория значения: class , interface , enum , table и др. classof(value) Таблица класса или nil instanceof(value, class) Является ли значение экземпляром указанного класса или его подкласса implements(value, interface) Реализует ли значение указанный интерфейс isenum(value) Является ли значение перечислением typeargs(value) Аргументы типов для обобщённого экземпляра typecheck(value, expected, label) Проверка соответствия значения ожидаемому типу super(self, class, name, ...) Вызов базовой реализации метода name Вспомогательные функции для таблиц и списков ​ Функция Описание foreach(t, fn) Вызывает fn для каждого элемента map(t, fn) Возвращает новый список с результатами вызова fn filter(t, fn) Оставляет только элементы, одобренные предикатом fn reduce(t, fn, acc) Сворачивает список в одно значение find(t, fn) Первый элемент, одобренный fn , либо nil any(t, fn) / all(t, fn) Проверка: хотя бы один / все элементы удовлетворяют предикату count(t, fn) Количество подходящих элементов contains(t, value) / indexof(t, value) Проверка наличия и поиск позиции keys(t) / values(t) Список ключей / значений таблицы copy(t) / merge(a, b) Поверхностная копия и объединение range(a, b, step) Числовой диапазон в виде списка sum(t) / min(t) / max(t) Агрегатные числовые операции reverse(t) / slice(t, from, to) Разворот порядка элементов и срез подсписка flatten(t) / unique(t) Выравнивание вложенных списков и удаление дубликатов Вспомогательные функции для строк и чисел ​ Функция Описание split(str, sep) / join(t, sep) Разделение строки и объединение списка trim(str) Удаление пробелов по краям строки startswith(str, s) / endswith(str, s) Проверка префикса и суффикса clamp(x, lo, hi) Ограничение числа диапазоном lerp(a, b, t) Линейная интерполяция round(x) / sign(x) Округление и знак числа default(value, fallback) Возвращает value , либо fallback , если value равен nil Управляемые модули ​ Управляемые модули регистрируются и загружаются в окружении скрипта через команду give . Модуль Mang.Reflection доступен сразу, а Mang.Patches активирует возможности перехвата методов. Модуль Содержимое Mang.Patches installed unpatchOwner unpatchTarget unpatchAll Mang.Reflection types hasType members staticMembers constructible patchTargets resolvePatch lua give Mang. Patches give Mang. Reflection print (Mang. Patches . installed ()) print (Mang. Reflection . hasType ( &quot;UnityEngine.Transform&quot; )) Подробнее об атрибутах перехвата и объекте frame читайте в разделе Патчинг методов , а о добавлении компонентов Unity - в разделе Инъекция классов в Unity ."},{"url":"ru/mlua/types.html","title":"Типы и аннотации | MLua","text":"Типы и аннотации ​ Аннотации типов не являются обязательными. Они сообщают компилятору ожидаемый тип значения и проверяются до запуска вашего скрипта. Где разрешены аннотации ​ lua local count : number = 0 local function Scale (value: number , factor: number ): number return value * factor end function Attach (target: object ): object return target end class Player public health : number = 100 private name : string = &quot;&quot; public function Heal (amount: number ): number self . health = self . health + amount return self . health end end Встроенные имена типов ​ Имя Значение any Любое значение. Совместимо со всеми типами в обе стороны. object Корневой тип. Любое значение приводимо к нему. nil Значение nil. Присваивается любой аннотации. boolean true или false . number Целое число или число с плавающей точкой. string Текстовая строка. table Таблицы Lua. Экземпляры классов MLua используют userdata. function Любая вызываемая сущность. userdata Нативный или управляемый дескриптор. void Отсутствие возвращаемого значения. Имя любого объявленного класса, интерфейса или enum также является типом. Составные имена разрешаются через пространства имён, например UnityEngine.Vector3 . Совместимость и присваивание ​ any совместим с любым типом данных. nil можно присвоить переменной с любой аннотацией. object принимает любое значение, включая литералы таблиц. Класс совместим со своими базовыми классами и интерфейсами, которые он реализует. Параметры типов взаимно совместимы внутри области видимости своего дженерика. Во всех остальных случаях типы должны совпадать по категории и имени. lua local function Accept (value: object ) end Accept ( 1 ) Accept ( &quot;text&quot; ) Accept ({}) Accept ( nil ) Вывод типов ​ Если у локальной переменной указана аннотация типа, а вызываемый метод является универсальным, аннотация помогает определить целевой тип: lua local function Attach (cube: GameObject ): CubeRotator local rotator : CubeRotator = cube : AddComponent () local resolved : CubeRotator = cube : GetComponent () return resolved end Здесь cube - параметр функции. CubeRotator должен быть объявленным классом компонента. Оба вызова получают CubeRotator как запрошенный тип, поэтому явный аргумент дженерика можно опустить. Запросы типов ​ lua local isPlayer = instanceof (value, Player) local canDrink = implements (value, IDrink) local typeName = typeof (value) local kindName = kindof (value) local classTable = classof (value) Функция Результат instanceof true , если значение является экземпляром класса или его наследника implements true , если класс значения реализует указанный интерфейс typeof Имя объявленного типа в виде строки kindof Категория типа: class , interface , enum , table , number и т.д. classof Таблица самого класса или nil для обычных значений"}];
  function esc(value) {
    return String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }

  function pageUrl(url) {
    // INDEX urls are relative to Build/Docs; resolve them from the current HTML file.
    const current = window.location.href;
    const here = new URL('.', current);
    return new URL(url, new URL('../'.repeat(Math.max(0, window.location.pathname.split('/').filter(Boolean).length - 2)), here)).href;
  }

  function openSearch() {
    if ($('.manglua-search-overlay')) return;
    const overlay = document.createElement('div');
    overlay.className = 'manglua-search-overlay';
    overlay.innerHTML = '<div class="manglua-search-backdrop"></div><div class="manglua-search-dialog" role="dialog" aria-modal="true" aria-label="Search"><input class="manglua-search-input" placeholder="Search…" autocomplete="off"><div class="manglua-search-results"></div></div>';
    document.body.append(overlay);
    const input = $('.manglua-search-input', overlay);
    const results = $('.manglua-search-results', overlay);
    const render = () => {
      const query = input.value.trim().toLowerCase();
      if (!query) {
        results.innerHTML = '<div class="manglua-search-empty">Type to search the documentation</div>';
        return;
      }
      const words = query.split(/\s+/).filter(Boolean);
      const hits = INDEX.map(page => {
        const hay = (page.title + ' ' + page.text).toLowerCase();
        let score = 0;
        for (const word of words) if (hay.includes(word)) score++;
        if (page.title.toLowerCase().includes(query)) score += 4;
        return [score, page];
      }).filter(([score]) => score > 0).sort((a,b) => b[0] - a[0]).slice(0, 12);
      results.innerHTML = hits.length
        ? hits.map(([, page]) => '<a class="manglua-search-result" href="' + esc(pageUrl(page.url)) + '"><strong>' + esc(page.title) + '</strong><span>' + esc(page.text.slice(0, 220)) + '…</span></a>').join('')
        : '<div class="manglua-search-empty">No results</div>';
    };
    input.addEventListener('input', render);
    input.focus();
    render();
    const close = () => overlay.remove();
    $('.manglua-search-backdrop', overlay).addEventListener('click', close);
    const keydown = e => { if (e.key === 'Escape') { close(); document.removeEventListener('keydown', keydown); } };
    document.addEventListener('keydown', keydown);
  }

  function initSearch() {
    $$('button.DocSearch').forEach(button => {
      if (button.dataset.mangluaSearchBound) return;
      button.dataset.mangluaSearchBound = '1';
      button.addEventListener('click', event => {
        event.preventDefault();
        event.stopImmediatePropagation();
        openSearch();
      }, true);
    });
  }

  function init() { initTheme(); initSearch(); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init, { once: true });
  else init();
})();
